//! Verifies `Compound` iteration order against JDK 21 `HashMap<String, Integer>` fixtures
//! generated by `tools/javamap-fixtures/GenOrder.java`.

use serde::Deserialize;
use zenith_nbt::{Compound, NbtString, Tag};

#[derive(Debug, Deserialize)]
struct FixtureFile {
    java_version: String,
    cases: Vec<OrderCase>,
    utf16_cases: Vec<Utf16OrderCase>,
}

#[derive(Debug, Deserialize)]
struct OrderCase {
    name: String,
    ops: Vec<Op>,
    expected_order: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Op {
    op: String,
    #[serde(default)]
    key: String,
}

#[derive(Debug, Deserialize)]
struct Utf16OrderCase {
    name: String,
    inserted_keys: Vec<Vec<u16>>,
    expected_hashes: Vec<i32>,
    expected_order: Vec<Vec<u16>>,
}

#[test]
fn compound_matches_jdk21_hashmap_iteration_order() {
    let raw = include_str!("fixtures/javamap_order.json");
    let fixture: FixtureFile = serde_json::from_str(raw).expect("valid fixture JSON");
    assert!(
        !fixture.cases.is_empty(),
        "fixture from Java {} must contain test cases",
        fixture.java_version
    );

    for case in &fixture.cases {
        let mut map = Compound::new();
        let mut seq = 0i32;
        for op in &case.ops {
            match op.op.as_str() {
                "put" => {
                    map.insert(op.key.as_str(), Tag::Int(seq));
                    seq += 1;
                }
                "remove" => {
                    map.remove(op.key.as_str());
                }
                "copy" => {
                    map = map.clone();
                }
                other => panic!("unknown fixture op '{other}' in case '{}'", case.name),
            }
        }

        let actual_order: Vec<String> = map
            .try_iter()
            .unwrap_or_else(|e| panic!("unexpected error in case '{}': {e}", case.name))
            .map(|(k, _)| k.as_str().expect("UTF-8 fixture key").to_owned())
            .collect();

        assert_eq!(
            actual_order, case.expected_order,
            "iteration order mismatch for JDK {} fixture case '{}'",
            fixture.java_version, case.name
        );
    }
}

#[test]
fn compound_matches_jdk21_utf16_and_lone_surrogate_order() {
    let raw = include_str!("fixtures/javamap_order.json");
    let fixture: FixtureFile = serde_json::from_str(raw).expect("valid fixture JSON");

    for case in &fixture.utf16_cases {
        let mut map = Compound::new();
        for (i, units) in case.inserted_keys.iter().enumerate() {
            let key = NbtString::from_utf16(units.clone());
            assert_eq!(
                key.java_hash_code(),
                case.expected_hashes[i],
                "Java String.hashCode mismatch for key {i} in '{}'",
                case.name
            );
            map.insert(key, Tag::Int(i as i32));
        }

        let actual_order: Vec<Vec<u16>> =
            map.try_iter().unwrap().map(|(k, _)| k.to_utf16()).collect();

        assert_eq!(
            actual_order, case.expected_order,
            "UTF-16 iteration order mismatch in '{}'",
            case.name
        );
    }
}
